function downloadProject(){save();const backup={...captureCompleteProject(),savedAt:new Date().toISOString()};download(JSON.stringify(backup,null,2),'map-workspace-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('所有圖層與設定已儲存，並下載專案備份')}
$('save-project').onclick=downloadProject;$('project-download').onclick=downloadProject;$('project-open').onclick=()=>$('project-file').click();
function repairNamedRegions(){for(const layer of state.layers)for(const o of layer.objects){if(o.type!=='polygon'||o.boxInputMode==='ordered'||!Array.isArray(o.boxVertices)||o.boxVertices.length<3)continue;try{const points=orderedPolygon(o.boxVertices);o.points=points;o.boxVertices=o.boxVertices.slice(0,points.length).map((v,i)=>({name:v.name||'點 '+(i+1),position:[...points[i]]}));o.boxInputMode='ordered';repairedRegionCount++}catch{}}}
function sanitizePreferences(){repairNamedRegions();const defaults={unit:'nm',format:'dms',color:'#f3ba68',basemap:'vector',routes:true,fixes:true,grid:true,selectedRoutes:null,referenceVisibility:{},selectedWaypointIds:null};state.settings={...defaults,...state.settings};const s=state.settings;s.cursorDisplay=cursorVisibility(s.cursorDisplay).mode;if(!['nm','km','m'].includes(s.unit))s.unit='nm';if(!['dms','decimal'].includes(s.format))s.format='dms';if(window.MPS_BUNDLE||!['vector','street','satellite'].includes(s.basemap))s.basemap='vector';if(!/^#[\da-f]{6}$/i.test(s.color))s.color='#f3ba68';if(s.selectedRoutes!==null)s.selectedRoutes=Array.isArray(s.selectedRoutes)?s.selectedRoutes.filter(x=>typeof x==='string').slice(0,300):null;if(!s.referenceVisibility||typeof s.referenceVisibility!=='object')s.referenceVisibility={};for(const key of ['routes','fixes','grid'])s[key]=s[key]!==false;for(const l of state.layers)l.opacity=clampOpacity(l.opacity);s.baseOpacity=clampOpacity(s.baseOpacity);s.routeOpacity=clampOpacity(s.routeOpacity);s.fixOpacity=clampOpacity(s.fixOpacity);s.referenceOpacity=s.referenceOpacity&&typeof s.referenceOpacity==='object'?s.referenceOpacity:{};for(const id of Object.keys(s.referenceOpacity))s.referenceOpacity[id]=clampOpacity(s.referenceOpacity[id]);s.customColors=Array.isArray(s.customColors)?s.customColors.filter(c=>/^#[\da-f]{6}$/i.test(c)).slice(0,2000):[];if(s.selectedWaypointIds!==null)s.selectedWaypointIds=Array.isArray(s.selectedWaypointIds)?s.selectedWaypointIds.filter(x=>typeof x==='string'):null;state.instruments||={};for(const name of ['ruler','protractor']){const data=state.instruments[name]||{};const normalized={visible:data.visible===true,x:Number.isFinite(data.x)?Math.max(0,Math.min(1,data.x)):.52,y:Number.isFinite(data.y)?Math.max(0,Math.min(.88,data.y)):.45,rotation:Number.isFinite(data.rotation)?data.rotation%360:0};if(name==='ruler'){normalized.range=null;if(data.range&&Number.isFinite(data.range.fromM)&&Number.isFinite(data.range.toM)&&data.range.fromM>=0&&data.range.toM>data.range.fromM&&/^#[\da-f]{6}$/i.test(data.range.color))normalized.range={fromM:data.range.fromM,toM:data.range.toM,color:data.range.color}}else{normalized.range=null;if(data.range&&Number.isFinite(data.range.from)&&Number.isFinite(data.range.to)&&data.range.from>=0&&data.range.from<=360&&data.range.to>=0&&data.range.to<=360&&data.range.from!==data.range.to&&/^#[\da-f]{6}$/i.test(data.range.color))normalized.range={from:data.range.from,to:data.range.to,color:data.range.color}}if(data.lock&&Array.isArray(data.lock.point)&&data.lock.point.length===2&&data.lock.point.every(Number.isFinite)&&Math.abs(data.lock.point[0])<=90&&Math.abs(data.lock.point[1])<=180)normalized.lock={point:[...data.lock.point]};normalized.scale=Number.isFinite(data.scale)?Math.max(.2,Math.min(3,data.scale)):1;normalized.ranges=Array.isArray(data.ranges)?data.ranges.filter(r=>r&&/^#[\da-f]{6}$/i.test(r.color)&&Number.isFinite(name==='ruler'?r.fromM:r.from)&&Number.isFinite(name==='ruler'?r.toM:r.to)).slice(0,200):data.range?[{...data.range,id:uid(),name:'標色範圍 1',visible:true}]:[];state.instruments[name]=normalized}}
$('project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('專案檔超過 20 MB');const imported=validateProject(JSON.parse(await file.text()));download(JSON.stringify(state,null,2),'map-workspace-before-open-'+Date.now()+'.json','application/json');snapshot();state=imported;sanitizePreferences();selected=null;$('editor-panel').hidden=true;setTool('pan');refreshUI();save('已開啟專案，原專案已下載備份')}catch(e){toast('開啟失敗：'+e.message)}e.target.value=''};
function escapeXML(s){return String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}
function exportKML(){const layer=activeLayer();const placemarks=layer.objects.map(o=>{const p=o.points.map(p=>`${p[1]},${p[0]},${p[2]||0}`);if(o.type==='polygon')p.push(p[0]);const coordinates='<altitudeMode>'+escapeXML(o.altitudeMode||'absolute')+'</altitudeMode><coordinates>'+p.join(' ')+'</coordinates>',geometry=o.type==='point'?'<Point>'+coordinates+'</Point>':o.type==='line'?'<LineString>'+coordinates+'</LineString>':'<Polygon><outerBoundaryIs><LinearRing>'+coordinates+'</LinearRing></outerBoundaryIs></Polygon>';const c=o.color.slice(1),color='ff'+c.slice(4,6)+c.slice(2,4)+c.slice(0,2);return`<Placemark><name>${escapeXML(o.name)}</name><description>${escapeXML(o.description||'')}</description><Style><LineStyle><color>${color}</color><width>2</width></LineStyle><PolyStyle><color>30${color.slice(2)}</color></PolyStyle><IconStyle><color>${color}</color></IconStyle></Style>${geometry}</Placemark>`}).join('');download('<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>'+escapeXML(layer.name)+'</name>'+placemarks+'</Document></kml>',layer.name.replace(/[<>:"/\\|?*]/g,'_')+'.kml','application/vnd.google-earth.kml+xml');toast('已匯出目前圖層的 '+layer.objects.length+' 個物件')}
$('export-kml').onclick=exportKML;$('import-kml').onclick=()=>$('kml-file').click();
$('kml-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('KML 超過 10 MB');reportActiveProgress(5,'讀取 KML');const xml=new DOMParser().parseFromString(await file.text(),'application/xml');reportActiveProgress(15,'解析 KML');if(xml.querySelector('parsererror'))throw Error('XML 格式不正確');const tags=(root,name)=>[...root.getElementsByTagNameNS('*',name)],objects=[];const placemarks=tags(xml,'Placemark');let parsedMarks=0;for(const mark of placemarks){if(parsedMarks%40===0){reportActiveProgress(15+parsedMarks/placemarks.length*65,'解析 KML');await new Promise(r=>setTimeout(r,0))}parsedMarks++;const name=tags(mark,'name')[0]?.textContent||'匯入標繪',description=tags(mark,'description')[0]?.textContent||'';const geometries=[...mark.getElementsByTagName('*')].filter(n=>['Point','LineString','Polygon'].includes(n.localName));for(const g of geometries){if(g.localName==='Polygon'&&tags(g,'innerBoundaryIs').length)throw Error('不支援含孔洞的多邊形；請先轉為單環');const raw=tags(g,'coordinates')[0]?.textContent?.trim();if(!raw)continue;let points=raw.split(/\s+/).map(s=>{const p=s.split(',').map(Number);return[p[1],p[0],p[2]??0]});const type=g.localName==='Point'?'point':g.localName==='LineString'?'line':'polygon';if(type==='polygon'&&points.length>1&&points[0][0]===points.at(-1)[0]&&points[0][1]===points.at(-1)[1])points.pop();const rawColor=tags(mark,'color')[0]?.textContent?.trim();let color=state.settings.color;if(/^[\da-f]{8}$/i.test(rawColor))color='#'+rawColor.slice(6,8)+rawColor.slice(4,6)+rawColor.slice(2,4);objects.push({id:uid(),name,description,type,points,color,altitudeMode:tags(g,'altitudeMode')[0]?.textContent||'clampToGround'})}}if(!objects.length)throw Error('沒有 Point、LineString 或 Polygon');const layer={id:uid(),name:file.name.replace(/\.kml$/i,''),visible:true,objects};validateProject({version:2,layers:[layer],activeLayerId:layer.id});snapshot();state.layers.push(layer);state.activeLayerId=layer.id;save('已匯入 '+objects.length+' 個幾何物件，並建立獨立圖層。其他 KML 中繼資料未保留。');renderObjects();renderLayers();openPanel('layers-panel');map.fitBounds(L.latLngBounds(objects.flatMap(o=>o.points)),{padding:[40,40],maxZoom:10})}catch(e){toast('匯入失敗：'+e.message)}e.target.value=''};
function refreshUI(){sanitizePreferences();renderPalette();$('unit').value=state.settings.unit;$('coordinate-format').value=state.settings.format;$('drawing-color').value=state.settings.color;$('basemap').value=state.settings.basemap;$('grid').checked=state.settings.grid;$('show-routes').checked=state.settings.routes;$('show-fixes').checked=state.settings.fixes;setBasemap();renderLayers();renderObjects();renderRouteList();renderRoutes();renderReferences();waypointPicker.renderList();waypointPicker.renderMap();renderGrid();updateCursor();updateInstrumentControls();drawProtractor();renderInstruments();updateScale();renderAxes();updateOpacityInputs();renderRangeLists();renderAirports();if($('cursor-display'))$('cursor-display').value=cursorVisibility(state.settings.cursorDisplay).mode;if($('altitude-unit'))$('altitude-unit').value=state.settings.altitudeUnit||'ft';if($('ruler-snap'))$('ruler-snap').checked=state.settings.rulerSnap!==false;}
map.on('move zoom resize',()=>{updateScale();renderAxes();if(!gestures.size)renderInstruments()});map.on('moveend',renderGrid);map.on('zoomend moveend resize',repositionAreaNames);window.addEventListener('resize',()=>requestAnimationFrame(()=>{map.invalidateSize({pan:false});renderInstruments()}));
function network(){$('network').textContent=navigator.onLine?'● 連線':'● 離線'}window.addEventListener('online',network);window.addEventListener('offline',network);network();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true}};
