function clampOpacity(v){return Number.isFinite(v)?Math.max(0,Math.min(1,v)):1}
function originalOpacityControl(name,value,apply){const b=document.createElement('button');b.className='opacity-button';let current=clampOpacity(value);const paint=()=>{b.textContent='透明度 '+Math.round(current*100)+'%';b.title='100% → 75% → 25% 循環（數值為可見度）';b.setAttribute('aria-label',name+' 透明度 '+Math.round(current*100)+'%')};paint();b.onclick=()=>{current=current===1?.75:current===.75?.25:1;apply(current);paint()};return b}
function nameVisible(layer,key){return (layer[key]??layer.names)===true}
function layerStyle(layer,apply,mode='single'){const row=document.createElement('div');row.className='row';for(const [key,label] of mode==='split'?[['areaNames','區域名稱'],['pointNames','點名稱']]:[['names','名稱']]){const button=document.createElement('button');const update=()=>{button.textContent=(nameVisible(layer,key)?'隱藏':'顯示')+label;button.setAttribute('aria-pressed',String(nameVisible(layer,key)))};update();button.onclick=()=>{snapshot();layer[key]=!nameVisible(layer,key);update();apply()};row.append(button)}const color=document.createElement('input');color.type='color';color.value=layer.color||'#75dfc8';color.setAttribute('aria-label','圖層顏色 '+(layer.name||''));color.onchange=()=>{snapshot();layer.color=color.value;apply()};row.append(color);return row}
// Scan horizontal slices from the southern edge; fit the complete label inside
// the polygon, including concave outlines, instead of using its bounding corner.
function lowerLeftLabel(points,width,height){const ys=points.map(p=>p.y),minY=Math.min(...ys),maxY=Math.max(...ys);const spans=y=>{const xs=[];for(let i=0,j=points.length-1;i<points.length;j=i++){const a=points[j],b=points[i];if((a.y>y)!==(b.y>y))xs.push(a.x+(y-a.y)*(b.x-a.x)/(b.y-a.y))}xs.sort((a,b)=>a-b);return xs.reduce((a,x,i)=>{if(i%2===0)a.push([x,xs[i+1]]);return a},[])};for(let bottom=maxY-5;bottom-height>minY;bottom-=3){let intervals=spans(bottom);const levels=[bottom-height,...ys.filter(y=>y>bottom-height&&y<bottom).flatMap(y=>[y-.01,y+.01])];for(const y of levels){const next=[];for(const [a,b]of intervals)for(const [c,d]of spans(y)){const l=Math.max(a,c),r=Math.min(b,d);if(r-l>=width+10)next.push([l,r])}intervals=next}if(intervals.length)return {x:intervals[0][0]+5,y:bottom-height}}return null}
function addAreaName(group,points,name,opacity,key){const content=document.createElement('span');content.textContent=name;const label=L.tooltip({permanent:true,interactive:false,direction:'center',className:'area-name-label',opacity,mpsStableKey:key}).setContent(content).setLatLng(points[0]).addTo(group);label.areaPoints=points;positionAreaName(label)}
function positionAreaName(label){const el=label.getElement();if(!el)return;const width=el.offsetWidth,height=el.offsetHeight,p=lowerLeftLabel(label.areaPoints.map(p=>map.latLngToLayerPoint(p)),width,height);el.style.visibility=p?'visible':'hidden';if(p)label.setLatLng(map.layerPointToLatLng([p.x+width/2,p.y+height/2]))}
function repositionAreaNames(){for(const group of [draw,referenceGroup])group.eachLayer(l=>{if(l.areaPoints)positionAreaName(l)})}

function applyBasemapOpacity(){const alpha=clampOpacity(state.settings.baseOpacity);street.setOpacity(alpha);satellite.setOpacity(alpha);land.eachLayer(l=>{l.setStyle?.({opacity:alpha,fillOpacity:.9*alpha})});street.bringToBack();satellite.bringToBack()}
function applyRouteOpacity(){routeLines.eachLayer(l=>{const name=[...routePaths].find(([,v])=>v===l)?.[0],prefs=state.settings.routeStyles?.[name]||{};l.setStyle({opacity:clampOpacity(state.settings.routeOpacity)*(prefs.opacity??1),color:prefs.color||state.settings.routeColor||'#6ed7bd'});if(state.settings.routeNames)l.bindTooltip(l.getPopup()?.getContent()?.querySelector('b')?.textContent||'',{permanent:true})});fixes.eachLayer(l=>l.setStyle?.({opacity:clampOpacity(state.settings.fixOpacity),fillOpacity:clampOpacity(state.settings.fixOpacity)}))}
function applyReferenceOpacity(){referenceGroup.getLayers().filter(l=>l.areaPoints).forEach(l=>referenceGroup.removeLayer(l));referenceGroup.eachLayer(l=>{const id=l.options.referenceId,ref=references.find(r=>r.id===id),prefs=state.settings.referenceStyles?.[id]||{};l.setStyle?.({opacity:clampOpacity(state.settings.referenceOpacity?.[id]),fillOpacity:(l instanceof L.CircleMarker?1:.025)*clampOpacity(state.settings.referenceOpacity?.[id]),color:prefs.color||ref?.color});l.unbindTooltip();if(l instanceof L.CircleMarker){const at=l.getLatLng(),i=ref.points.findIndex(p=>Math.abs(p[0]-at.lat)<1e-7&&Math.abs(p[1]-at.lng)<1e-7),name=ref.pointNames?.[i]||ref.name+' · 頂點 '+(i+1);l.bindTooltip(name,{permanent:nameVisible(prefs,ref.type==='polygon'?'pointNames':'names')});const el=l.getElement();if(el){el.setAttribute('role','button');el.setAttribute('aria-label',name)}}else if(ref.type==='polygon'){if(nameVisible(prefs,'areaNames'))addAreaName(referenceGroup,ref.pathPoints||ref.points,ref.name,clampOpacity(state.settings.referenceOpacity?.[id]))}else l.bindTooltip(ref.name,{permanent:prefs.names===true})})}
function updateOpacityInputs(){for(const [panel,key,label,apply] of [['basemap-panel','baseOpacity','底圖',applyBasemapOpacity],['routes-panel','routeOpacity','航路',applyRouteOpacity],['waypoints-panel','fixOpacity','航點',()=>waypointPicker.renderMap()]]){let mount=$(key+'-control');if(!mount){mount=document.createElement('div');mount.id=key+'-control';$(panel).querySelector('.section-body').prepend(mount)}mount.replaceChildren(opacityControl(label,state.settings[key],v=>{snapshot();state.settings[key]=v;apply();save()}));if(key!=='baseOpacity'){const setting={name:label,names:state.settings[key==='routeOpacity'?'routeNames':'fixNames']!==false,color:state.settings[key==='routeOpacity'?'routeColor':'fixColor']||'#75dfc8'};mount.append(layerStyle(setting,()=>{state.settings[key==='routeOpacity'?'routeNames':'fixNames']=setting.names;state.settings[key==='routeOpacity'?'routeColor':'fixColor']=setting.color;renderRoutes();waypointPicker.renderMap();save()}))}}for(const ref of references){const el=[...$('reference-list').children].find(n=>n.querySelector('label')?.textContent===ref.name);if(el&&!el.querySelector('.reference-style')){state.settings.referenceStyles||={};const prefs=state.settings.referenceStyles[ref.id]||={name:ref.name,names:false,color:ref.color};const row=layerStyle(prefs,()=>{applyReferenceOpacity();save()},ref.type==='polygon'?'split':'single');row.classList.add('reference-style');el.append(row)}}}
function eraseObject(id){const f=getObject(id);if(!f)return;snapshot();f.layer.objects=f.layer.objects.filter(o=>o.id!==id);selected=null;inspected=null;$('editor-panel').hidden=true;map.closePopup();renderObjects();renderLayers();save('已清除，可按復原還原')}
function inspectObject(id){revealWorkspaceItem('object:'+id);const f=getObject(id);if(!f)return;if(inspected===id){map.closePopup();selectObject(id);return}inspected=id;const content=showPointPopup(f.object.name,f.object.points[0]);const desc=document.createElement('p');desc.textContent=(f.object.description||'')+' · 高度 '+altitudeText(f.object.points[0][2]||0);content.append(desc);if(f.object.points.length>1&&!isCompassArc(f.object))content.append(makePointsTable(f.object.points,f.object.name));const edit=document.createElement('button');edit.textContent='編輯詳細資料';edit.onclick=()=>{map.closePopup();selectObject(id)};content.append(edit);L.popup().setLatLng(f.object.points[0]).setContent(content).openOn(map)}
function deleteLayer(id){const l=state.layers.find(l=>l.id===id);if(!l)return;snapshot();state.layers=state.layers.filter(l=>l.id!==id);if(!state.layers.length)state.layers.push({id:uid(),name:'標繪圖層 1',visible:true,objects:[]});state.activeLayerId=state.layers[0].id;selected=null;$('editor-panel').hidden=true;renderLayers();renderObjects();save('已刪除圖層，可復原')}
$('delete-layer').onclick=()=>deleteLayer(state.activeLayerId);
