function updateOperationGuide(){if(!$('operation-current'))return;const names={pan:'平移／選取',point:'新增標記',line:'繪製線段',polygon:'繪製區域',free:'自由繪圖',erase:'橡皮擦',tape:'鐵捲尺',compass:'圓規'};let next={pan:'拖曳地圖平移。長按物件顯示移動／旋轉／縮放控制。點一下標記查看資料，再點一次進入修訂；雙擊地圖可輸入區域座標。',point:'點選地圖放置標記；新物件會加入目前編輯圖層。',line:'點選頂點；至少兩點後按上方 ✓ 完成，Esc 取消。',polygon:'點選至少三個頂點，再按上方 ✓ 完成區域，Esc 取消。',free:'按住並拖動繪圖，放開儲存；可沿尺規邊緣畫線。',erase:'點選自己的標記清除；上方復原可還原刪除。',tape:tapeStart?'起點已選：請選第二點，完成後在線上顯示距離。':'請先選第一點，再選第二點建立測距線。',compass:compassState()?.visible?'圓心點一下可解鎖／鎖定。雙擊按住筆端拖動畫弧；直接放開則標點。收起圓規後可連點兩次弧線進入修訂。':'請點選圓心並輸入半徑。'}[tool]||'';if(['line','polygon'].includes(tool))next='已選 '+draftPoints.length+' 點。'+next;$('operation-current').textContent='目前：'+(names[tool]||tool);$('operation-next').textContent=next}
