const printTemplateUI=document.createElement('fieldset');printTemplateUI.innerHTML='<legend>常用版型</legend><label>選擇版型<select id="print-template-list"></select></label><div class="row"><button id="print-template-apply">套用版型</button><button id="print-template-delete">刪除自訂版型</button></div><label>自訂版型名稱<input id="print-template-name" placeholder="例如 A3 任務圖"></label><button id="print-template-save">儲存目前設定為版型</button><p id="print-template-status" role="status"></p>';printDialog.querySelector('h2').after(printTemplateUI);const printCalibrationLabel=document.createElement('label');printCalibrationLabel.className='print-footer-option';printCalibrationLabel.innerHTML='<input id="print-calibration" type="checkbox"> 顯示 50 mm 紙上檢查線與對應地圖距離';$('print-footer').closest('label').after(printCalibrationLabel);$('print-calibration').checked=state.settings.printCalibration!==false;
function currentPrintTemplate(){return{paper:$('print-paper').value,orientation:$('print-orientation').value,ratio:Number($('print-ratio').value),margins:{kind:$('print-margins').value,...paperMargins()},footer:$('print-footer').checked,calibration:$('print-calibration').checked}}
function invalidatePrint(){clearLivePrint();pdfPreview=null;$('print-download').disabled=true;$('print-status').textContent='設定已變更，請重新產生預覽。'}
function storePrintPreferences(){state.settings.printPreferences=currentPrintTemplate();state.settings.printCalibration=$('print-calibration').checked;save();invalidatePrint()}
function applyPrintTemplate(raw){const p=readPrintTemplate(raw);$('print-paper').value=p.paper;$('print-orientation').value=p.orientation;$('print-ratio').value=p.ratio;$('print-margins').value=p.margins?.kind||'narrow';for(const side of ['top','right','bottom','left'])$('margin-'+side).value=p.margins?.[side]??12.7;$('print-footer').checked=p.footer!==false;$('print-calibration').checked=p.calibration!==false;custom.hidden=$('print-margins').value!=='custom';state.settings.printMargins={kind:$('print-margins').value,...paperMargins()};state.settings.printFooter=$('print-footer').checked;storePrintPreferences()}
function renderPrintTemplates(){const select=$('print-template-list');select.replaceChildren();for(const p of [...builtinPrintTemplates,...(state.settings.printTemplates||[])]){const o=document.createElement('option');o.value=p.id;o.textContent=p.name;select.append(o)}}
$('print-template-apply').onclick=()=>{try{const t=[...builtinPrintTemplates,...(state.settings.printTemplates||[])].find(t=>t.id===$('print-template-list').value);if(t){applyPrintTemplate(t);$('print-template-status').textContent='已套用 '+t.name}}catch(e){$('print-template-status').textContent=e.message}};$('print-template-save').onclick=()=>{try{const name=$('print-template-name').value.trim();if(!name)throw Error('請填寫版型名稱');const template=readPrintTemplate({...currentPrintTemplate(),id:uid(),name});state.settings.printTemplates||=[];const old=state.settings.printTemplates.findIndex(p=>p.name===name);if(old>=0)state.settings.printTemplates[old]=template;else state.settings.printTemplates.push(template);save();renderPrintTemplates();$('print-template-list').value=template.id;$('print-template-status').textContent='已儲存版型；會隨專案備份保留。'}catch(e){$('print-template-status').textContent=e.message}};$('print-template-delete').onclick=()=>{const id=$('print-template-list').value;if(builtinPrintTemplates.some(p=>p.id===id))return $('print-template-status').textContent='內建版型不能刪除';state.settings.printTemplates=(state.settings.printTemplates||[]).filter(p=>p.id!==id);save();renderPrintTemplates();$('print-template-status').textContent='已刪除自訂版型'};for(const id of ['print-paper','print-orientation','print-ratio','print-calibration'])$(id).addEventListener('change',storePrintPreferences);renderPrintTemplates();if(state.settings.printPreferences){try{applyPrintTemplate(state.settings.printPreferences)}catch{}}
function printCalibrationMarkup(p,width){const pixelsPerMm=width/p.mw,d=calibrationDistance(p.ratio,factor(state.settings.unit)),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('print-calibration');svg.setAttribute('viewBox','0 0 55 13');svg.setAttribute('aria-label','50 mm 紙上比例尺檢查線');svg.style.cssText='position:absolute;right:'+5*pixelsPerMm+'px;bottom:'+4*pixelsPerMm+'px;width:'+55*pixelsPerMm+'px;height:'+13*pixelsPerMm+'px;z-index:860;pointer-events:none';const text=(d.toFixed(precision(state.settings.unit,3))+' '+state.settings.unit.toUpperCase()+' | 1:'+p.ratio).replace(/&/g,'&amp;');svg.innerHTML='<rect width="55" height="13" fill="#fff" fill-opacity=".95"/><text x="2" y="4" font-size="2.2" fill="#111">50 mm · Print at 100%</text><path d="M2 7H52M2 5.5V8.5M12 6V8M22 6V8M32 6V8M42 6V8M52 5.5V8.5" stroke="#111" stroke-width=".25"/><text x="2" y="11.5" font-size="2.2" fill="#111">'+text+'</text>';return svg}
function addPrintCalibration(root,p,width){if(p.calibrationEnabled)root.append(printCalibrationMarkup(p,width))}
function drawPdfCalibration(doc,p){if(!p.calibrationEnabled)return;const x=p.x+p.mw-60,y=p.y+p.mh-17;doc.setFillColor(255,255,255);doc.rect(x,y,55,13,'F');doc.setDrawColor(0,0,0);doc.setTextColor(0,0,0);doc.setLineWidth(.25);doc.line(x+2,y+7,x+52,y+7);for(let i=0;i<=5;i++)doc.line(x+2+i*10,y+(i===0||i===5?5.5:6),x+2+i*10,y+(i===0||i===5?8.5:8));doc.setFontSize(6.2);doc.text('50 mm | Print at 100%',x+2,y+4);doc.text(calibrationDistance(p.ratio,factor(p.calibrationUnit)).toFixed(p.calibrationPrecision)+' '+p.calibrationUnit.toUpperCase()+' | 1:'+p.ratio,x+2,y+11.5)}
